const raw = $('Retell Tool Call').first().json.body || $('Retell Tool Call').first().json;
let args;
if (raw.arguments !== undefined) {
  args = typeof raw.arguments === 'string' ? JSON.parse(raw.arguments) : raw.arguments;
} else if (raw.args !== undefined) {
  args = typeof raw.args === 'string' ? JSON.parse(raw.args) : raw.args;
} else {
  args = raw;
}

const telefonoRaw = String(args.telefono || '').trim();
const telefono = telefonoRaw.replace(/\D/g, '');
if (!/^\d{9}$/.test(telefono)) {
  return [{ json: {
    error: 'telefono_invalido', modificado: false,
    mensaje: 'El teléfono que me has dado no parece correcto. ¿Me puedes repetir los nueve dígitos?'
  }}];
}

const nueva_fecha = String(args.nueva_fecha || '').trim();
const nueva_hora  = String(args.nueva_hora  || '').trim();

const HORARIOS = {
  1: { inicio: 9 * 60 + 30, fin: 19 * 60 },
  2: { inicio: 9 * 60 + 30, fin: 19 * 60 },
  3: { inicio: 9 * 60 + 30, fin: 14 * 60 },
  4: { inicio: 9 * 60 + 30, fin: 19 * 60 },
  5: { inicio: 9 * 60 + 30, fin: 14 * 60 },
  6: { inicio: 9 * 60 + 30, fin: 14 * 60 }
};
const diasSemana = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];

function spainToUTC(dateStr, timeStr) {
  const asZ = new Date(dateStr + 'T' + timeStr + ':00Z');
  const inMadrid = new Date(asZ.toLocaleString('en-US', { timeZone: 'Europe/Madrid' }));
  return new Date(asZ.getTime() + (asZ - inMadrid));
}

const nuevaFechaUTC   = spainToUTC(nueva_fecha, nueva_hora);
const localNuevaFecha = new Date(nuevaFechaUTC.toLocaleString('en-US', { timeZone: 'Europe/Madrid' }));
const diaSemana  = localNuevaFecha.getDay();
const horarioDia = HORARIOS[diaSemana];

if (!horarioDia) {
  return [{ json: {
    error: 'dia_cerrado', modificado: false,
    mensaje: 'Los domingos estamos cerrados. ¿Quieres un día entre semana?'
  }}];
}

const horaMin = localNuevaFecha.getHours() * 60 + localNuevaFecha.getMinutes();
if (horaMin < horarioDia.inicio) {
  return [{ json: {
    error: 'fuera_horario', modificado: false,
    mensaje: 'Esa hora es antes de que abramos. Empezamos a las nueve y media.'
  }}];
}
if (horaMin >= horarioDia.fin - 30) {
  const esMediodia = horarioDia.fin === 14 * 60;
  return [{ json: {
    error: 'fuera_horario', modificado: false,
    mensaje: 'Los ' + diasSemana[diaSemana] + ' cerramos a las ' + (esMediodia ? 'dos de la tarde' : 'siete de la tarde') + ' y necesitamos tiempo para la cita.'
  }}];
}

return [{ json: {
  telefono,
  fecha_actual: String(args.fecha_actual || '').trim(),
  hora_actual:  String(args.hora_actual  || '').trim(),
  nueva_fecha, nueva_hora
}}];

const { telefono, fecha_actual, hora_actual, nueva_fecha, nueva_hora } = $('Parsear Argumentos').first().json;
const filas = $('Google Sheets - Leer Citas').all();

const fila = filas.find(f => {
  const d = f.json;
  const telMatch   = String(d['Teléfono'] || '').replace(/\D/g, '') === telefono;
  const fechaMatch = String(d['Fecha']    || '').trim() === fecha_actual;
  const activa     = d['Estado'] === 'CONFIRMADA' || d['Estado'] === 'MODIFICADA';
  const horaMatch  = !hora_actual || String(d['Hora'] || '').trim() === hora_actual;
  return telMatch && fechaMatch && activa && horaMatch;
});

if (!fila) {
  return [{ json: {
    encontrado: false, modificado: false,
    mensaje: 'No encontré ninguna cita activa para ese teléfono y fecha.'
  }}];
}

const servicio = fila.json['Servicio'];
// Duración según servicio — tolera nombres con/sin acentos y variantes
function durFor(servicio) {
  const s = String(servicio || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
  const TABLA = [
    [/blanqueamiento/, 60],
    [/endodoncia/, 60],
    [/implante|cirugia/, 60],
    [/limpieza/, 45],
    [/empaste/, 45],
    [/prostodoncia|protesis|corona|puente/, 45],
    [/periodoncia|encia/, 45],
    [/extracc/, 30],
    [/ortodoncia/, 30],
    [/revis|general|consulta/, 30],
  ];
  for (const [re, min] of TABLA) if (re.test(s)) return min;
  return 30;
}
const duracion = durFor(servicio);

function spainToUTC(dateStr, timeStr) {
  const asZ = new Date(dateStr + 'T' + timeStr + ':00Z');
  const inMadrid = new Date(asZ.toLocaleString('en-US', { timeZone: 'Europe/Madrid' }));
  return new Date(asZ.getTime() + (asZ - inMadrid));
}

const nuevaFechaInicio = spainToUTC(nueva_fecha, nueva_hora);
const nuevaFechaFin    = new Date(nuevaFechaInicio.getTime() + duracion * 60000);
const localInicio      = new Date(nuevaFechaInicio.toLocaleString('en-US', { timeZone: 'Europe/Madrid' }));

const diasSemana = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];
const meses = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];

return [{ json: {
  encontrado: true,
  calendarEventId: fila.json['Calendar_Event_ID'],
  nombre:   fila.json['Nombre'],
  servicio, telefono, fecha_actual, nueva_fecha, nueva_hora,
  nuevaFechaInicio: nuevaFechaInicio.toISOString(),
  nuevaFechaFin:    nuevaFechaFin.toISOString(),
  fechaTexto: diasSemana[localInicio.getDay()] + ' ' + localInicio.getDate() + ' de ' + meses[localInicio.getMonth()]
}}];

const datos = $('Encontrar Cita en Sheets').first().json;
const eventos = $('Google Calendar - Verificar Nuevo Slot').all();

const newStart = new Date(datos.nuevaFechaInicio);
const newEnd = new Date(datos.nuevaFechaFin);

// Excluir el propio evento para evitar falso conflicto
const eventosOtros = eventos
  .map(e => e.json)
  .filter(e => e.status !== 'cancelled' && e.id !== datos.calendarEventId && (e.start?.dateTime || e.start?.date));

const hayConflicto = eventosOtros.some(ev => {
  const evStart = new Date(ev.start.dateTime || ev.start.date + 'T00:00:00');
  const evEnd = new Date(ev.end.dateTime || ev.end.date + 'T00:00:00');
  return newStart < evEnd && newEnd > evStart;
});

return [{ json: { ...datos, slotDisponible: !hayConflicto } }];
